sp_widget.client_script:
api.controller = function($sce, spUtil,$location) {
    var c = this;

    c.decodeHTML = function(html) {
        if (!html) return "";
        return html
            .replace(/&lt;/g, "<")
            .replace(/&gt;/g, ">")
            .replace(/&amp;/g, "&")
            .replace(/&quot;/g, '"')
            .replace(/&#39;/g, "'");
    };

    c.renderHTML = function() {
        var decoded = c.decodeHTML(c.data.raw_statement);
        return $sce.trustAsHtml(decoded);
    };

		c.goBack=function () {

			const prev = sessionStorage.getItem('prevPage');
					//alert(prev);

			if (prev) {
				$location.url(prev);
			} else {
				// fallback if nothing stored
				window.history.back();
			}
		}

		c.raiseDispute = function()
		{
			 $location.url('?id=create_dispute&table=x_ctans_incentnow_incentiq_dispute&sys_id=-1&statement_id='+c.data.statementId);
		}

		c.submitForApproval = function() {

				c.server.get({
						action: "submit_for_approval",
						statement_id: c.data.statementId
				}).then(function(response) {

						if (response.data.success) {
								spUtil.addInfoMessage(response.data.message);
								// Refresh data if needed
								c.server.update();
						} else {
								spUtil.addErrorMessage(response.data.message);
						}

				});

		};


	  // ✅ initialize from server
    c.selectedUser = c.data.selectedUser;
    c.selectedPeriod = c.data.selectedPeriod;

    // OPTIONAL (if you want direct display)
    c.selectedUserName = c.data.selectedUserName;
    c.selectedPeriodName = c.data.selectedPeriodName;



};

