       BACK BUTTON / EXISTING ELEMENTS
       -------------------------------------------------------- */

    .back-btn-wrapper {
        display: none !important;
    }

    .b {
        padding-left: 1rem !important;
        padding-top: 0.8rem !important;
        margin-right: 0 !important;
        font-size: 1.4rem;
    }


    /* --------------------------------------------------------
       MODAL
       -------------------------------------------------------- */

    .modal {
        overflow-y: auto;
        overflow-x: hidden;
    }

    .modal-dialog {
        width: calc(100% - 2rem);
        max-width: none;
        margin: 1rem auto;
    }

    .modal-content {
        width: 100%;
        max-width: 100%;
        overflow-x: hidden;
    }


    /* --------------------------------------------------------
       LONG FORMS / LONG CONTENT
       -------------------------------------------------------- */

    /*
       Any element explicitly marked as a long-form container
       can scroll horizontally on small screens.
    */

    .long-form,
    .form-scroll,
    .table-responsive {
        width: 100%;
        max-width: 100%;
        overflow-x: auto;
        overflow-y: hidden;
        -webkit-overflow-scrolling: touch;
    }


    /* --------------------------------------------------------
       FORM CONTROLS
       -------------------------------------------------------- */

    input,
    select,
    textarea {
        max-width: 100%;
    }

    textarea {
        resize: vertical;
    }


    /* --------------------------------------------------------
       PREVENT TEXT FROM BREAKING THE PAGE
       -------------------------------------------------------- */

    img,
    iframe,
    video {
        max-width: 100%;
    }

    .code {
        display: inline-block;
        max-width: 100%;
        overflow-x: auto;
        vertical-align: middle;
    }
}


/* ============================================================
   VERY SMALL MOBILE DEVICES
   ============================================================ */

@media (max-width: 480px) {

    .statement-headers {
        padding: 0.8rem 0.3rem;
    }

    .left-info h2 {
