    }

    .commission-statement-container .statement-plan-title {
        font-size: 1.6rem !important;
    }
}

@media (max-width: 767px) {

    /* ============================================================
       EARNING RULE - MOBILE HORIZONTAL SCROLL
       ============================================================ */

    .earning-rules-table {
        width: 100%;
