        white-space: nowrap;
    }

    .earning-rule-col,
    .earning-object-col,
    .earning-field-col,
    .earning-type-col,
    .earning-level-col,
    .earning-condition-col,
    .earning-value-col {
        padding-top: 1.2rem;
        padding-bottom: 1.2rem;
        padding-left: 1rem;
        padding-right: 1rem;
        font-size: 1.4rem;
    }

    .earning-rule-name,
    .earning-rule-type,
    .earning-rule-value {
