}

@media (max-width: 767px) {

    /* ============================================================
       PAYOUT COMPONENT - MOBILE HORIZONTAL SCROLL
       ============================================================ */

    .payout-table {
        width: 100%;
        max-width: 100%;
        overflow-x: auto !important;
        overflow-y: hidden;

        -webkit-overflow-scrolling: touch;
        display: block;

        padding-bottom: 5px;
    }

    .payout-table table {
