        white-space: nowrap;
    }

    .payout-component-col {
        padding-left: 1rem;
        padding-right: 1rem;
        padding-top: 1.2rem;
        padding-bottom: 1.2rem;
        font-size: 1.4rem;
    }

    .payout-detail {
        padding: 0.8rem 1rem;
        font-size: 1.3rem;
        white-space: nowrap;
    }

    .payout-amount {
        white-space: nowrap;
        font-size: 1.4rem;
    }

    .payout-total-label {
        padding-left: 1rem;
        padding-top: 1.2rem;
        font-size: 1.8rem;
        white-space: nowrap;
    }

    .payout-total-value {
        padding-top: 1.2rem;
        font-size: 1.8rem;
        white-space: nowrap;
    }
}

sp_widget.script:
(function() {

data.currencySymbol = gs.getProperty(
'x_ctans_incentnow.currency_symbol',
    '$'
);
    data.statementId = $sp.getParameter("statement_id");

    if (data.statementId) {

        var grState = new GlideRecordSecure("x_ctans_incentnow_incentive_statement");
        if (grState.get($sp.getParameter("statement_id"))) {
            data.raw_statement = grState.statement + "";

            if (grState.get(data.statementId)) {

                data.raw_statement = grState.statement + "";


                // 🔹 Quota Attainment
                data.quotaAttainment = {
                    percentage: grState.quota_percentage || 0,
                    achieved: grState.quota_achieved || 0,
                    quota: grState.quota_target || 0
                };
                var quota = parseFloat(grState.getValue("target_quota")) || 0;
                var attainment = parseFloat(grState.getValue("quota_attainment")) || 0;
                data.quotaAttainment = {
                    percentage: attainment || 0,
                    quota: quota || 0,
                    achieved: parseFloat(((quota * attainment) / 100).toFixed(2))
                };
                var helper = new IncentNowStatementHelper();

                var result = helper.getQTDAndYTD(
                    grState.getValue("user"),
                    grState.getValue("fiscal_period")
                );
                // QTD Commission
								data.qtdCommission = {
										amount: parseFloat(result.qtd_commission) || 0,
										transactions: result.qtd_transactions || 0
								};

								// YTD Commission
								data.ytdCommission = {
										amount: parseFloat(result.ytd_commission) || 0,
										transactions: result.ytd_transactions || 0
								};
                var changeResult = helper.getPeriodChange(
                    grState.getValue("user"),
                    grState.getValue("fiscal_period")
                );
                // 🔹 Period Commission
                data.periodCommission = {
                    amount: parseFloat(grState.getValue("total_commission")) || 0,
                    change: changeResult.change_percentage + "%",
                    transactions: 0
                };


                // 🔹 Current Period
                data.currentPeriod = {
                    period: grState.period_name || "",
                    totalCommission: grState.total_commission || 0,
                    transactions: grState.total_transactions || 0
                };

            }

						if (input && input.action == "submit_for_approval") {
								data.success = false;

								var stmtGR = new GlideRecordSecure("x_ctans_incentnow_incentive_statement");
								if (stmtGR.get(input.statement_id)) {

										if (stmtGR.getValue("status") != "statement_generated") {
												data.message = "Only Statement Generated records can be submitted for approval.";
												return;
										}

										stmtGR.setValue("status", "pending_approval");
										stmtGR.update();

										data.success = true;
										data.message = "Statement submitted for approval successfully.";
								}

								return;
						}

						data.status = grState.getValue("status");
						data.statusDisplay = grState.getDisplayValue("status");

            // ✅ IMPORTANT: send selected values
            data.selectedUser = grState.getValue("user");
            data.selectedPeriod = grState.getValue("fiscal_period");

            // ✅ ALSO send display names (best practice)
            data.selectedUserName = grState.getDisplayValue("user");
            data.selectedPeriodName = grState.getDisplayValue("fiscal_period");
            //	}
            //		}

            var totalComm = parseFloat(grState.getValue("total_commission") || 0);


        }
    }

})();
